import fs from "fs";
import zlib from "zlib";

const pts = JSON.parse(fs.readFileSync(process.argv[2]));
const [xmin,xmax,zmin,zmax,cell,ymin,ymax,out] = [
  parseFloat(process.argv[3]), parseFloat(process.argv[4]),
  parseFloat(process.argv[5]), parseFloat(process.argv[6]),
  parseFloat(process.argv[7]), parseFloat(process.argv[8]),
  parseFloat(process.argv[9]), process.argv[10]];

const W = Math.round((xmax-xmin)/cell), H = Math.round((zmax-zmin)/cell);
const img = Buffer.alloc(W*H*3);
const best = new Float32Array(W*H).fill(-1e9);
const xyz = pts.xyz, rgb = pts.rgb;
for (let i=0;i<xyz.length;i++){
  const [x,y,z]=xyz[i];
  if (y<ymin||y>ymax) continue;
  const cx=Math.floor((x-xmin)/cell), cz=Math.floor((z-zmin)/cell);
  if(cx<0||cz<0||cx>=W||cz>=H) continue;
  const idx=cz*W+cx;
  if (y > best[idx]) { best[idx]=y; img[idx*3]=rgb[i][0]; img[idx*3+1]=rgb[i][1]; img[idx*3+2]=rgb[i][2]; }
}
// PNG encode
function crc32(buf){let t=[];for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0;}let c=0xFFFFFFFF;for(const b of buf)c=t[(c^b)&0xFF]^(c>>>8);return (c^0xFFFFFFFF)>>>0;}
function chunk(type,data){const len=Buffer.alloc(4);len.writeUInt32BE(data.length);const td=Buffer.concat([Buffer.from(type),data]);const crc=Buffer.alloc(4);crc.writeUInt32BE(crc32(td));return Buffer.concat([len,td,crc]);}
const ihdr=Buffer.alloc(13);ihdr.writeUInt32BE(W,0);ihdr.writeUInt32BE(H,4);ihdr[8]=8;ihdr[9]=2;
const raw=Buffer.alloc(H*(W*3+1));
for(let y=0;y<H;y++){raw[y*(W*3+1)]=0;img.copy(raw,y*(W*3+1)+1,y*W*3,(y+1)*W*3);}
// flip vertically so +z is up
const rawF=Buffer.alloc(H*(W*3+1));
for(let y=0;y<H;y++){rawF[y*(W*3+1)]=0;img.copy(rawF,y*(W*3+1)+1,(H-1-y)*W*3,(H-y)*W*3);}
const png=Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk("IHDR",ihdr),chunk("IDAT",zlib.deflateSync(rawF)),chunk("IEND",Buffer.alloc(0))]);
fs.writeFileSync(out,png);
console.log("wrote",out,W,"x",H, "x right:",xmin,"->",xmax," z up:",zmin,"->",zmax);
EOF
