import fs from "fs";
const cams = JSON.parse(fs.readFileSync("inputs/cameras.json")).views;
const pts = JSON.parse(fs.readFileSync("inputs/points.json"));
function quatToMat(q){const[x,y,z,w]=q;return[1-2*(y*y+z*z),2*(x*y-z*w),2*(x*z+y*w),2*(x*y+z*w),1-2*(x*x+z*z),2*(y*z-x*w),2*(x*z-y*w),2*(y*z+x*w),1-2*(x*x+y*y)];}
// usage: region3.mjs IMG u0 v0 u1 v1 rmax gmax bmax [dmax]  (color upper bounds; use 255 to disable)
const [img,u0,v0,u1,v1,rmax,gmax,bmax,dmaxS]=process.argv.slice(2);
const c=cams.find(c=>c.name.startsWith(img));
const dmax=dmaxS?parseFloat(dmaxS):9;
const R=quatToMat(c.quat);
const f=0.5*c.height/Math.tan(c.fov_deg*Math.PI/360);
const cx=c.width/2,cy=c.height/2;
const sel=[];
for(let i=0;i<pts.xyz.length;i++){
  const cc=pts.rgb[i];
  if(cc[0]>+rmax||cc[1]>+gmax||cc[2]>+bmax)continue;
  const p=pts.xyz[i];
  const dx=p[0]-c.pos[0],dy=p[1]-c.pos[1],dz=p[2]-c.pos[2];
  const vx=R[0]*dx+R[3]*dy+R[6]*dz,vy=R[1]*dx+R[4]*dy+R[7]*dz,vz=R[2]*dx+R[5]*dy+R[8]*dz;
  if(vz>-0.05)continue;
  const d=-vz;
  if(d>dmax)continue;
  const u=cx+f*vx/d,v=cy-f*vy/d;
  if(u>=+u0&&u<=+u1&&v>=+v0&&v<=+v1)sel.push({p,d});
}
console.log("count",sel.length);
if(sel.length<3)process.exit(0);
// robust bbox: 5th-95th percentile per axis
for(const[label,ax]of[["x",0],["y",1],["z",2]]){
  const a=sel.map(s=>s.p[ax]).sort((p,q)=>p-q);
  const lo=a[Math.floor(0.03*(a.length-1))],hi=a[Math.floor(0.97*(a.length-1))];
  console.log(label,lo.toFixed(2),"..",hi.toFixed(2));
}
const ds=sel.map(s=>s.d).sort((a,b)=>a-b);
console.log("d",ds[0].toFixed(2),"..",ds[ds.length-1].toFixed(2),"median",ds[Math.floor(ds.length/2)].toFixed(2));
EOF
